(async()=>{
 const status=document.querySelector('#cms-status'),start=document.querySelector('#cms-start'),local=document.querySelector('#cms-local');
 const isLocal=['localhost','127.0.0.1','[::1]'].includes(location.hostname);
 let config;
 async function launch(localMode){const b=localMode?local:start;b.disabled=true;status.textContent='正在加载内容编辑器…';try{if(localMode){const response=await fetch('http://localhost:8081/api/v1',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'info'}),signal:AbortSignal.timeout(3000)});if(!response.ok)throw Error('请先运行 npm run cms:local，再重试。')}await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/admin/vendor/decap-cms.js';s.onload=resolve;s.onerror=()=>reject(Error('编辑器资源无法加载，请刷新页面重试。'));document.head.append(s)});const options={...config,local_backend:localMode?{url:'http://localhost:8081/api/v1',allowed_hosts:['127.0.0.1']}:false};if(localMode)options.publish_mode='simple';window.CMS.init({config:options});document.body.classList.add('cms-open')}catch(e){status.textContent=e.message||'编辑器无法启动，请检查部署配置。';b.disabled=false}}
 try{const r=await fetch('/admin/config.json',{cache:'no-store'});if(!r.ok)throw Error('无法读取后台配置，请重新构建网站。');const data=await r.json();config=data.config;if(data.configured){status.textContent='配置已就绪。通过 GitHub 登录后即可管理内容。';start.hidden=false;start.onclick=()=>launch(false)}else{status.textContent='首次部署尚未配置 GitHub 仓库和网站域名。当前不会连接任何占位仓库。';document.querySelector('#cms-setup').hidden=false}if(isLocal){local.hidden=false;document.querySelector('#local-help').hidden=false;local.onclick=()=>launch(true)}}catch(e){status.textContent=e.message}
})();
